import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';class ChatScreen extends StatefulWidget{final String sellerId,sellerName,productId,productTitle;const ChatScreen({super.key,required this.sellerId,required this.sellerName,required this.productId,required this.productTitle});@override State<ChatScreen> createState()=>_S();}class _S extends State<ChatScreen>{final t=TextEditingController();String get u=>FirebaseAuth.instance.currentUser!.uid;String get id=>([u,widget.sellerId]..sort()).join('_');Future<void> send()async{final v=t.text.trim();if(v.isEmpty)return;final r=FirebaseFirestore.instance.collection('chats').doc(id);await r.set({'participants':[u,widget.sellerId],'lastMessage':v,'lastMessageAt':FieldValue.serverTimestamp(),'productId':widget.productId,'productTitle':widget.productTitle},SetOptions(merge:true));await r.collection('messages').add({'senderId':u,'text':v,'createdAt':FieldValue.serverTimestamp()});t.clear();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.sellerName)),body:Column(children:[Expanded(child:StreamBuilder<QuerySnapshot>(stream:FirebaseFirestore.instance.collection('chats').doc(id).collection('messages').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(reverse:true,children:s.data!.docs.map((d){final x=d.data() as Map<String,dynamic>;return ListTile(title:Align(alignment:x['senderId']==u?Alignment.centerRight:Alignment.centerLeft,child:Text(x['text']??'')));}).toList());})),Row(children:[Expanded(child:TextField(controller:t,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Tulis pesan...'))),IconButton(onPressed:send,icon:const Icon(Icons.send))]) ]));}}